import {createCMSRepository} from './repository.mjs';
import {mountEditor} from './editor-vendor.mjs';
import {cmsConfig} from '../../hub-cms/config.mjs';
import {renderArticle,validateArticle} from '../../hub-cms/render.mjs';
import {stable} from '../../hub-cms/body.mjs';
import {bindCanvas,applyCanvasText} from './visual-adapter.mjs';
import {documentMetrics,documentChanged} from './document-state.mjs';
import {articleState,categoryLabel,readableDate,libraryRows} from './library.mjs';
export async function bootCMS({document=globalThis.document,repo=createCMSRepository(),request=globalThis.fetch}={}){
 const d=document,form=d.querySelector('#cms-form'),status=d.querySelector('#cms-status'),list=d.querySelector('#cms-library'),history=d.querySelector('#cms-history'),preview=d.querySelector('#cms-preview'),field=name=>form.elements.namedItem(name);
 let articles=[],article=null,presentation=null,editors={},busy=false,related=[],importReview=null,reviewBase=null,savedBase=null,loading=false,saving=false,canvasBase=null,canvasRegion=null;
 const node=(tag,text)=>{const n=d.createElement(tag);if(text!==undefined)n.textContent=text;return n;},say=text=>status.textContent=text;
 function state(){if(loading||form.hidden)return;const value=content(),dirty=documentChanged(savedBase,value),metrics=documentMetrics(value.body);d.querySelector('#cms-document-state').textContent=saving?'Saving…':dirty?'Unsaved changes':'Saved'+(article?.updated_at?' · '+readableDate(article.updated_at):'');d.querySelector('#cms-document-state').dataset.state=saving?'saving':dirty?'dirty':'saved';d.querySelector('#cms-word-count').textContent=metrics.words+' words · approximately '+metrics.minutes+' min read';for(const name of ['seo_title','meta_description'])d.querySelector('[data-cms-length="'+name+'"]').textContent=field(name).value.length+' characters · write a clear, useful summary; length is not a ranking rule.';return dirty;}
 const canLeave=()=>!state()||d.defaultView.confirm('Discard unsaved changes to this draft?');
 d.defaultView.addEventListener('beforeunload',event=>{if(state()){event.preventDefault();event.returnValue='';}});
 d.addEventListener('click',event=>{if(event.target.closest?.('a[href]')&&state()&&!canLeave())event.preventDefault();});
 form.addEventListener('input',state);form.addEventListener('change',state);form.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();form.requestSubmit(d.querySelector('#cms-save'));}});
 const template=key=>request('/hub-cms/presentation/'+key+'.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('Article presentation is unavailable.');return r.json();});
 function renderLibrary(){list.replaceChildren();const rows=libraryRows(articles,{search:d.querySelector('#cms-search').value,category:d.querySelector('#cms-category-filter').value,state:d.querySelector('#cms-state-filter').value,order:d.querySelector('#cms-order').value});for(const a of rows){const row=node('tr');for(const [index,text] of [a.draft.title||'Untitled draft',categoryLabel(a.draft.category),a.published_revision_id?articleState(a):'Draft · never published',a.draft.slug||'Unset',readableDate(a.updated_at),a.published_revision_id?readableDate(a.published_content?.published_at):'Not yet published'].entries()){const cell=node('td',text);if(index===2)cell.className='cms-state';row.append(cell);}const cell=node('td');cell.className='cms-library-actions';for(const label of ['Edit','Preview','History']){const b=node('button',label);b.type='button';b.addEventListener('click',()=>run(async()=>{await select(a);if(label==='Preview')previewContent(content(),{separate:true});if(label==='History')d.querySelector('#cms-history-title').scrollIntoView?.({block:'start'});}));cell.append(b);}row.append(cell);list.append(row);}if(!rows.length){const r=node('tr'),cell=node('td','No articles match these filters.');cell.colSpan=7;r.append(cell);list.append(r);}}
 function choices(name,options,selected){const root=d.querySelector('[data-cms-choices="'+name+'"]');root.replaceChildren();for(const [value,label] of options){const wrapper=node('label'),input=node('input');input.type='checkbox';input.name=name;input.value=value;input.checked=selected.includes(value);wrapper.append(input,d.createTextNode(' '+label));root.append(wrapper);}}
 function renderRelated(){const root=d.querySelector('[data-cms-choices="related"]'),q=d.querySelector('#cms-related-search').value.toLowerCase();root.replaceChildren();for(const a of articles.filter(a=>a.id!==article?.id)){const label=(a.draft.title||a.guide_key)+' · '+categoryLabel(a.draft.category),selected=related.includes(a.guide_key);if(!selected&&!label.toLowerCase().includes(q))continue;const wrapper=node('label'),input=node('input');input.type='checkbox';input.name='related';input.value=a.guide_key;input.checked=selected;input.addEventListener('change',()=>{related=input.checked?[...related,a.guide_key]:related.filter(id=>id!==a.guide_key);renderRelated();state();});wrapper.append(input,d.createTextNode(' '+label));root.append(wrapper);}const selected=d.querySelector('#cms-related-selected');selected.replaceChildren();selected.append(d.createTextNode(related.length+' selected: '));for(const id of related){const a=articles.find(a=>a.guide_key===id),b=node('button',(a?.draft.title||id)+' ×');b.type='button';b.setAttribute('aria-label','Remove related guide '+(a?.draft.title||id));b.addEventListener('click',()=>{related=related.filter(x=>x!==id);renderRelated();state();});selected.append(b);}}
 function content(){const draft={version:1};for(const name of ['title','slug','category','intro','seo_title','meta_description'])draft[name]=field(name).value;draft.indexable=field('indexable').checked;draft.primary_intent=field('primary_intent').value||null;draft.published_at=field('published_at').value||null;draft.content_updated_at=article?.draft.content_updated_at||null;draft.related=[...related];for(const name of ['tools','components']){const checked=[...form.querySelectorAll('input[name="'+name+'"]:checked')].map(n=>n.value),prior=article?.draft[name]||presentation.baseline[name]||[];draft[name]=[...prior.filter(id=>checked.includes(id)),...checked.filter(id=>!prior.includes(id))];}draft.body={version:1,slots:Object.fromEntries(Object.entries(editors).map(([key,e])=>[key,e.get()]))};return draft;}
 function previewContent(value,{separate=false}={}){validateArticle(value,presentation,{knownGuides:articles.map(a=>a.guide_key)});const registry=articles.filter(a=>a.published_revision_id||a.id===article?.id).map(a=>({guide_key:a.guide_key,content:a.id===article?.id?value:(a.published_content||a.draft)})),html=renderArticle(value,presentation,registry,{preview:true});preview.srcdoc=html;preview.hidden=false;preview.setAttribute('title','Private article preview');if(separate){const w=d.defaultView.open('about:blank','_blank');if(w){w.opener=null;w.document.title='Private Apparition article preview';const meta=w.document.createElement('meta');meta.name='robots';meta.content='noindex,nofollow';w.document.head.append(meta);const iframe=w.document.createElement('iframe');iframe.title='Private article preview';iframe.setAttribute('sandbox','allow-scripts allow-same-origin');iframe.referrerPolicy='no-referrer';iframe.style.cssText='position:fixed;inset:0;width:100%;height:100%;border:0';iframe.srcdoc=html;w.document.body.append(iframe);}else say('Popup blocked; private preview is shown below.');}say('Private preview only. Draft has no public URL.');return html;}
 function openCanvas(){canvasBase=structuredClone(content());canvasRegion=null;d.querySelector('#cms-canvas-region').hidden=true;const html=previewContent(canvasBase);const frame=d.querySelector('#cms-canvas');frame.onload=()=>{bindCanvas(frame.contentDocument,canvasBase,presentation,region=>{canvasRegion=region;const panel=d.querySelector('#cms-canvas-region');panel.hidden=false;d.querySelector('#cms-canvas-description').textContent=region.editable?'Editing '+region.kind+' in private draft':'Complex formatting: use the structured editor for this region.';d.querySelector('#cms-canvas-text').value=(region.node.content||[]).map(n=>n.text||'').join('');d.querySelector('#cms-canvas-text').disabled=!region.editable;d.querySelector('#cms-canvas-apply').disabled=!region.editable;});};frame.srcdoc=html;d.querySelector('#cms-canvas-section').hidden=false;say('Private on-canvas text mode. Changes stay in the draft until Save Draft and explicit publication.');}
 function applyCanvas(){if(!canvasRegion)throw Error('Select an editable region first.');const patched=applyCanvasText(content(),canvasBase,canvasRegion,d.querySelector('#cms-canvas-text').value);editors[canvasRegion.slot].setNode(canvasRegion.path,patched.node);state();openCanvas();}
 d.querySelector('#cms-canvas-open').addEventListener('click',()=>{try{openCanvas();}catch(e){say(e.message);}});d.querySelector('#cms-canvas-apply').addEventListener('click',()=>{try{applyCanvas();}catch(e){say(e.message);}});d.querySelector('#cms-canvas-close').addEventListener('click',()=>d.querySelector('#cms-canvas-section').hidden=true);
 function clearReview(){importReview=null;reviewBase=null;d.querySelector('#cms-import-review').hidden=true;d.querySelector('#cms-docx-file').value='';d.querySelector('#cms-import-confirm').checked=false;}
 async function select(value,{force=false}={}){if(!force&&!canLeave())return;loading=true;d.querySelector('#cms-canvas-section').hidden=true;clearReview();article=value;presentation=await template(value?.seed_context.template_key||'generic');for(const e of Object.values(editors))e.destroy();editors={};const c=value?.draft||{...presentation.baseline,category:'potentiometers',body:{version:1,slots:{main:{type:'doc',content:[{type:'paragraph'}]}}}};form.reset();for(const name of ['title','slug','category','intro','seo_title','meta_description'])field(name).value=c[name];field('slug').readOnly=!!value?.published_revision_id;field('indexable').checked=c.indexable;field('primary_intent').replaceChildren();const supporting=node('option','Supporting guide / no primary nomination');supporting.value='';field('primary_intent').append(supporting);const expected=cmsConfig.intentByGuide[value?.guide_key];if(expected){const o=node('option','Primary authority: '+expected);o.value=expected;field('primary_intent').append(o);}field('primary_intent').value=c.primary_intent||'';field('primary_intent').disabled=true;field('published_at').value=c.published_at||'';d.querySelector('#cms-updated').textContent=c.content_updated_at?'Last published update: '+readableDate(c.content_updated_at):'Updated date is recorded on publication.';d.querySelector('#cms-editor-title').textContent=value?'Edit: '+(c.title||'Untitled draft'):'New draft';related=[...c.related];d.querySelector('#cms-related-search').value='';renderRelated();choices('tools',Object.entries(cmsConfig.tools).map(([id,t])=>[id,t.title]),c.tools);choices('components',Object.entries(cmsConfig.components).map(([id,t])=>[id,t.title]),c.components);
  const root=d.querySelector('#cms-body-editors');root.replaceChildren();for(const [key,doc] of Object.entries(c.body.slots)){const section=node('section'),label=node('h3',key==='main'?'Article body':'Further reference'),host=node('div');host.className='cms-editor';section.append(label,host);root.append(section);editors[key]=mountEditor(host,doc,presentation,state);}form.hidden=false;preview.hidden=true;history.replaceChildren();d.querySelector('#cms-publish').disabled=!value;if(value)await renderHistory();savedBase=stable(content());loading=false;state();
 }
 async function renderHistory(){const revisions=await repo.history(article.id);history.replaceChildren();if(!revisions.length)history.append(node('p','No published revisions yet.'));for(const revision of revisions){const p=node('p','Revision '+revision.revision_number+' · '+readableDate(revision.created_at)+' · '+revision.content.title+' · '+revision.state+' · '+(revision.actor?'Admin '+revision.actor:'Source migration')),inspect=node('button','Inspect / preview'),restore=node('button','Restore as new publication');inspect.type=restore.type='button';inspect.addEventListener('click',()=>{try{previewContent(revision.content);}catch(e){say(e.message);}});restore.addEventListener('click',()=>run(async()=>{const saved=await repo.save(article,revision.content,'RESTORE',revision.id);await reload(saved.id);say('Restored as a new revision. Pages updates after successful scheduled generation; historical snapshots remain immutable.');}));p.append(inspect,restore);history.append(p);}const imports=repo.imports?await repo.imports(article.id):[],root=d.querySelector('#cms-import-history');root.replaceChildren();if(!imports.length)root.append(node('p','No DOCX draft imports.'));for(const revision of imports){const p=node('p','Draft version '+revision.edit_version+' · '+readableDate(revision.created_at)+' · DOCX import · '+revision.content.title),b=node('button','Inspect imported draft');b.type='button';b.addEventListener('click',()=>{try{previewContent(revision.content);}catch(e){say(e.message);}});p.append(b);root.append(p);}}
 async function reload(id){articles=await repo.list();renderLibrary();if(id)await select(articles.find(a=>a.id===id),{force:true});}
 async function run(fn){if(busy)return;busy=true;d.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){say(e.message);}finally{busy=false;d.querySelectorAll('button').forEach(b=>b.disabled=false);d.querySelector('#cms-publish').disabled=!article;d.querySelector('#cms-import-accept').disabled=!importReview||!!importReview.errors.length;for(const e of Object.values(editors))e.refresh?.();saving=false;loading=false;state();}}
 async function reviewDOCX(bytes){if(!article)throw Error('Save the draft before importing.');const adapter=await import('./docx-vendor.mjs');reviewBase=content();importReview=await adapter.importDOCX(bytes,article,reviewBase,presentation,{DOMParser:d.defaultView.DOMParser});const root=d.querySelector('#cms-import-review'),notices=d.querySelector('#cms-import-notices'),diff=d.querySelector('#cms-import-diff');notices.replaceChildren();for(const message of [...importReview.errors,...importReview.warnings])notices.append(node('li',message));diff.replaceChildren();for(const change of importReview.diff){const block=node('section');block.append(node('h3',change.kind+' · '+change.change),node('p','Before: '+change.before),node('p','After: '+change.after));diff.append(block);}d.querySelector('#cms-import-summary').textContent=importReview.diff.length+' block/field changes. Protected blocks: '+importReview.protectedStatus+'. Nothing has been saved or published.';root.hidden=false;d.querySelector('#cms-import-confirm').checked=false;d.querySelector('#cms-import-accept').disabled=!!importReview.errors.length;return importReview;}
 async function acceptImport(){if(!importReview||importReview.errors.length)throw Error('Resolve blocked import before accepting.');if(!d.querySelector('#cms-import-confirm').checked)throw Error('Review the changes and acknowledge unsupported content first.');if(stable(content())!==stable(reviewBase))throw Error('Editor changed during review; parse the file again.');validateArticle(importReview.candidate,presentation,{knownGuides:articles.map(a=>a.guide_key)});const saved=await repo.importDraft(article,importReview.candidate);await reload(saved.id);say('DOCX accepted into a private draft snapshot. The published revision is unchanged. Preview, then publish separately.');}
 for(const id of ['cms-search','cms-category-filter','cms-state-filter','cms-order'])d.querySelector('#'+id).addEventListener(id==='cms-search'?'input':'change',renderLibrary);d.querySelector('#cms-related-search').addEventListener('input',renderRelated);
 d.querySelector('#cms-new').addEventListener('click',()=>run(()=>select(null)));d.querySelector('#cms-preview-button').addEventListener('click',()=>{try{previewContent(content(),{separate:true});}catch(e){say(e.message);}});
 d.querySelector('#cms-docx-export').addEventListener('click',()=>run(async()=>{const adapter=await import('./docx-vendor.mjs'),value=content();validateArticle(value,presentation,{knownGuides:articles.map(a=>a.guide_key)});const bytes=await adapter.exportDOCX(article,value),url=d.defaultView.URL.createObjectURL(new d.defaultView.Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})),a=node('a');a.href=url;a.download=(value.slug||'article')+'.docx';a.click();d.defaultView.setTimeout(()=>d.defaultView.URL.revokeObjectURL(url),1000);say('DOCX exported. Leave Apparition-controlled markers unchanged.');}));
 d.querySelector('#cms-docx-file').addEventListener('change',()=>run(async()=>{const file=d.querySelector('#cms-docx-file').files?.[0];if(!file)return;if(!file.name.toLowerCase().endsWith('.docx')||file.size>5_000_000)throw Error('Choose a DOCX file, maximum 5 MB.');await reviewDOCX(new Uint8Array(await file.arrayBuffer()));}));d.querySelector('#cms-import-cancel').addEventListener('click',()=>{clearReview();say('Import cancelled. Draft and publication are unchanged.');});d.querySelector('#cms-import-accept').addEventListener('click',()=>run(acceptImport));
 form.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const action=e.submitter?.value==='PUBLISH'?'PUBLISH':'DRAFT',value=content();validateArticle(value,presentation,{publishing:action==='PUBLISH',knownGuides:articles.map(a=>a.guide_key)});if(action==='PUBLISH'&&!d.defaultView.confirm('Publish this draft as a new public revision?'))return;saving=true;state();const saved=await repo.save(article,value,action);await reload(saved.id);say(action==='PUBLISH'?'Published revision saved. Public pages update after successful scheduled generation (normally five minutes; queueing can delay it).':'Private draft saved; public content is unchanged.');});});
 await run(async()=>{for(const c of cmsConfig.categories){for(const target of [field('category'),d.querySelector('#cms-category-filter')]){const option=node('option',c.title);option.value=c.id;target.append(option);}}await reload();say('CMS library ready. Publishing changes content, not presentation.');});return {content,select,previewContent,reviewDOCX,acceptImport,state,getEditors:()=>editors,openCanvas,applyCanvas};
}
if(typeof document!=='undefined')await bootCMS();
